import 'dart:convert';

import 'package:flutter_test/flutter_test.dart';
import 'package:mesh_mapper/utils/mvt_cells.dart';

/// Fixtures generated by the SERVER's dev/mvt_encoder.php — the decoder must
/// stay in lockstep with it (see MeshMapper_Server/docs/VECTOR_TILES.md).
///
/// `_knownTile`: layer "coverage", extent 4096, two features:
///   id=42 {i:-5, j:7, st:1} and id=43 {i:3, j:7, st:6}.
/// `_realTile`: an actual rendered z12 coverage tile (29 cells).
const _knownTile =
    'GmUKCGNvdmVyYWdlEhkIKhIGAAABAQICGAMiCwkAABoUAAAUEwAPEhsIKxIGAAMBAQIEGAMiDQnIAZADGhQAABQTAA8aAWkaAWoaAnN0IgIwCSICMA4iAjACIgIwBiICMAwogCB4Ag==';
const _realTile =
    '';

void main() {
  test('decodes the known two-feature tile exactly', () {
    final cells = decodeCoverageCells(base64Decode(_knownTile));
    expect(cells.length, 2);
    expect(cells[0].id, 42);
    expect(cells[0].i, -5);
    expect(cells[0].j, 7);
    expect(cells[0].st, 1);
    expect(cells[1].id, 43);
    expect(cells[1].i, 3);
    expect(cells[1].j, 7);
    expect(cells[1].st, 6);
  });

  test('decodes a real rendered tile with valid ids and categories', () {
    final cells = decodeCoverageCells(base64Decode(_realTile));
    expect(cells.length, 29);
    for (final cell in cells) {
      expect(cell.st, inInclusiveRange(1, 6));
      // id = ((i + 2^20) << 21) | (j + 2^20), computed arithmetically here
      // because dart2js truncates >32-bit bitwise ops (web build).
      final expectedId = (cell.i + 1048576) * 2097152 + (cell.j + 1048576);
      expect(cell.id, expectedId);
    }
  });

  test('garbage input decodes to empty, never throws', () {
    expect(decodeCoverageCells(base64Decode('aGVsbG8gd29ybGQ=')), isEmpty);
  });
}
